INSERT INTO config_versions(kind,version,status,data,notes,published_at) VALUES ('rules',1,'published','{"_note":"Seed defaults (placeholders until playtesting). Edited and versioned in the Command Center.","version":1,"c7_weights":{"clear":1,"concise":1,"concrete":1,"correct":1.5,"coherent":1,"complete":1,"courteous":1},"c7_level_cuts":{"strong":2.5,"good":1.5},"critical_business_cap":40,"critical_flags":{"commit_beyond_authority":"severe","confirmed_unverified_coverage":"severe","misstated_fact":"major","breached_privacy":"severe","abusive_tone":"major"},"recovery":{"incident_severity_downgrade":true,"note":"A recovery in the same call downgrades severe→major; history keeps both."},"account_health":{"weights":{"trust":0.4,"respect":0.3,"anger_inverse":0.3},"on_track_min":70,"watch_min":40,"severe_incident_override":"at_risk"},"portfolio_health":{"importance_weights":{"low":1,"medium":2,"high":3},"good_min":65,"fair_min":45},"team_health":{"weights":{"morale":0.5,"reliability":0.3,"workload_inverse":0.2},"good_min":65,"fair_min":45},"thought_unlocks":[{"index":1,"trust_min":6},{"index":2,"trust_min":8,"c7_courteous_avg_min":2}],"meters":{"min":0,"max":10,"max_delta_per_reply":3},"between_calls":{"anger_cooldown_per_day":1},"probation":{"policy":"remediation_then_boss_variant","remediation_calls":2,"max_probations_per_level":2,"demotion_on":"second_failed_probation_or_two_open_severe_incidents"},"option_order":{"seeded":true,"seed_source":"career.seed + '':'' + scenario_id + '':'' + node_id"},"lock_in":{"policy":"every_decision","alt":"consequential_only"}}'::jsonb,'Seed v1 (placeholder values until playtesting)',now());
INSERT INTO config_versions(kind,version,status,data,notes,published_at) VALUES ('economy',1,'published','{"version":1,"xp":{"base_by_type":{"instruction_call":50,"status_update_call":60,"feedback_call":70,"escalation_call":80,"email_mission":40,"boss_mission":150,"team_delegation":60,"team_coaching":80,"team_one_on_one":80,"remediation_call":40,"boss_variant":150},"performance_bonus_max":25,"level_multiplier":[1,1.2,1.4,1.6,1.8,2,2.2,2.5],"glossary_round_xp":5,"glossary_daily_cap":20},"coins":{"per_call_base":5,"performance_bonus_max":10,"boss_bonus":30,"promotion_bonus":100},"daily_goal":{"light":1,"steady":2,"driven":4,"unit":"calls_or_missions"},"streak":{"qualifying":"one call, email mission or boss per local day","freeze_covers_days":1,"freezes_max_held":2,"freeze_price":60},"quests":{"per_day":3,"refresh":"local midnight","seeded":true}}'::jsonb,'Seed v1 (placeholder values until playtesting)',now());
INSERT INTO config_versions(kind,version,status,data,notes,published_at) VALUES ('unlocks',1,'published','{"version":1,"navigation":{"path":"start","clients":"after_first_scorecard","inbox":"level>=2","glossary":"level>=2","journal":"after_first_incident_or_level>=2","achievements":"after_first_badge","quests":"after_onboarding","shop":"after_first_promotion","team":"level>=5"},"rule":"Hidden until unlocked; introduce with a one-line message."}'::jsonb,'Seed v1 (placeholder values until playtesting)',now());
INSERT INTO config_versions(kind,version,status,data,notes,published_at) VALUES ('theme',1,'published','{"version":1,"accent":"#2459E0","tints":{"blue":["#DCE8FF","#1F3F8F"],"coral":["#FFE3DA","#8A2E12"],"mint":["#D6F3E6","#0D5A3A"],"lime":["#E8F4CC","#3D5A0D"],"rose":["#FCE1EA","#8A1F45"],"sky":["#D6F0FA","#0E4F6B"],"butter":["#FFF0C2","#7A3E00"]},"rule":"Admin edits must pass a 4.5:1 contrast check for ink on tint and white on accent."}'::jsonb,'Seed v1 (placeholder values until playtesting)',now());
INSERT INTO config_versions(kind,version,status,data,notes,published_at) VALUES ('ladder',1,'published','[{"level":1,"title":"Trainee Associate","short_title":"Trainee","client_count":3,"team_size":0,"xp_threshold":500,"gates":{"all_required_calls":true,"xp_min":500,"portfolio_min":"good","no_open_severe_incident":true,"boss_passed":true},"skills_introduced":["Clear status updates","Asking for missing information","Staying within authority"],"unlocks":["path","clients"],"boss_scenario_id":"L1_BOSS_FIRST_REVIEW","promotion_message":"You proved you can keep a client informed without overpromising. Welcome to the team properly."},{"level":2,"title":"Associate","short_title":"Associate","client_count":4,"team_size":0,"xp_threshold":1100,"gates":{"all_required_calls":true,"xp_min":1100,"portfolio_min":"good","no_open_severe_incident":true,"boss_passed":true},"skills_introduced":["Certificates and renewals","Deadlines","Email missions"],"unlocks":["inbox","glossary"],"boss_scenario_id":"L2_BOSS_RENEWAL_AT_RISK","promotion_message":"You handle renewals and deadlines on your own now. Bigger accounts are coming your way."},{"level":3,"title":"Senior Associate","short_title":"Senior","client_count":5,"team_size":0,"xp_threshold":1900,"gates":{"all_required_calls":true,"xp_min":1900,"portfolio_min":"good","no_open_severe_incident":true,"boss_passed":true},"skills_introduced":["Claims coordination","Carrier and adjuster communication","Incomplete facts"],"unlocks":["journal"],"boss_scenario_id":"L3_BOSS_INCOMPLETE_CLAIM","promotion_message":"Claims don''t rattle you. You''re the one people ask when the facts are messy."},{"level":4,"title":"Executive Associate","short_title":"Executive","client_count":8,"team_size":0,"xp_threshold":3200,"gates":{"all_required_calls":true,"xp_min":3200,"portfolio_min":"good","no_open_severe_incident":true,"boss_passed":true},"skills_introduced":["De-escalation","Empathy under pressure","Prioritising several accounts"],"unlocks":["achievements_tiers"],"boss_scenario_id":"L4_BOSS_DOUBLE_ESCALATION","promotion_message":"You kept your head when two clients escalated at once. Time to help others do the same."},{"level":5,"title":"Assistant Team Lead","short_title":"ATL","client_count":10,"team_size":2,"xp_threshold":4800,"gates":{"all_required_calls":true,"xp_min":4800,"portfolio_min":"good","no_open_severe_incident":true,"boss_passed":true,"team_health_min":"good"},"skills_introduced":["Delegating routine work","Quality checks","Covering gaps"],"unlocks":["team","delegation_board"],"boss_scenario_id":"L5_BOSS_TEAMMATE_ERROR","promotion_message":"Your first team. Your job now is to make two people successful, not just yourself."},{"level":6,"title":"Team Lead","short_title":"TL","client_count":10,"team_size":4,"xp_threshold":6800,"gates":{"all_required_calls":true,"xp_min":6800,"portfolio_min":"good","no_open_severe_incident":true,"boss_passed":true,"team_health_min":"good"},"skills_introduced":["Coaching: diagnose, coach, follow up","Workload balance","Giving feedback"],"unlocks":["coaching_calls"],"boss_scenario_id":"L6_BOSS_HARD_DAY","promotion_message":"You coach, you balance, you follow up. The team leads look to you."},{"level":7,"title":"Manager (probationary)","short_title":"Manager","client_count":10,"team_size":8,"xp_threshold":9200,"gates":{"all_required_calls":true,"xp_min":9200,"portfolio_min":"good","no_open_severe_incident":true,"boss_passed":true,"team_health_min":"good"},"skills_introduced":["Capacity planning","Retention conversations","Reporting upward"],"unlocks":["unit_dashboard"],"boss_scenario_id":"L7_BOSS_QUARTERLY_REVIEW","promotion_message":"You''ve run a unit for a quarter. One more stretch and the role is yours."},{"level":8,"title":"Manager","short_title":"Manager","client_count":10,"team_size":10,"xp_threshold":12000,"gates":{"all_required_calls":true,"xp_min":12000,"portfolio_min":"good","no_open_severe_incident":true,"boss_passed":true,"team_health_min":"good"},"skills_introduced":["Account recovery","Strategic trade-offs","Judgment under pressure"],"unlocks":["ending"],"boss_scenario_id":"L8_BOSS_FINALE","promotion_message":"Manager. Everything you said on every call led here."}]'::jsonb,'Seed v1 (placeholder values until playtesting)',now());
INSERT INTO config_versions(kind,version,status,data,notes,published_at) VALUES ('flags',1,'published','[{"key":"registration_open","enabled":true,"description":"Allow new sign-ups"},{"key":"email_verification_required","enabled":true,"description":"Players must verify email before playing"},{"key":"maintenance_mode","enabled":false,"description":"Show maintenance page to players; admins unaffected"},{"key":"lock_in_consequential_only","enabled":false,"description":"Proposal P2: only consequential decisions open the lock-in sheet"},{"key":"probation_policy_rank_vs_chapter","enabled":false,"description":"Proposal P1 alternative: failure changes standing, content continues"},{"key":"reminders_enabled","enabled":true,"description":"Allow opt-in reminders"},{"key":"feedback_prompts","enabled":true,"description":"Ask opt-in feedback after calls"},{"key":"dev_autopublish_in_review","enabled":false,"description":"DEV ONLY: treat in_review content as playable"}]'::jsonb,'Seed v1 (placeholder values until playtesting)',now());
INSERT INTO config_versions(kind,version,status,data,notes,published_at) VALUES ('quests_pool',1,'published','[{"id":"q_calls_2","title":"Finish 2 calls","metric":"calls_completed","target":2,"reward":{"coins":10},"min_level":1,"weight":1,"status":"in_review"},{"id":"q_calls_3","title":"Finish 3 calls","metric":"calls_completed","target":3,"reward":{"coins":15},"min_level":1,"weight":1,"status":"in_review"},{"id":"q_concrete","title":"Earn Strong on Concrete","metric":"c7_strong:concrete","target":1,"reward":{"coins":10},"min_level":1,"weight":1,"status":"in_review"},{"id":"q_correct","title":"Earn Strong on Correct","metric":"c7_strong:correct","target":1,"reward":{"coins":10},"min_level":1,"weight":1,"status":"in_review"},{"id":"q_courteous","title":"Earn Strong on Courteous","metric":"c7_strong:courteous","target":1,"reward":{"coins":10},"min_level":1,"weight":1,"status":"in_review"},{"id":"q_email","title":"Complete an email mission","metric":"email_missions","target":1,"reward":{"coins":10},"min_level":2,"weight":1,"status":"in_review"},{"id":"q_glossary","title":"Finish a glossary round","metric":"glossary_rounds","target":1,"reward":{"coins":5},"min_level":2,"weight":1,"status":"in_review"},{"id":"q_no_incident","title":"Finish 2 calls with no incident","metric":"calls_no_incident","target":2,"reward":{"coins":15},"min_level":1,"weight":1,"status":"in_review"},{"id":"q_trust_up","title":"Raise any client''s trust","metric":"trust_gain","target":1,"reward":{"coins":10},"min_level":1,"weight":1,"status":"in_review"},{"id":"q_daily_goal","title":"Meet your daily goal","metric":"daily_goal_met","target":1,"reward":{"freeze":1},"min_level":1,"weight":1,"status":"in_review"},{"id":"q_delegate","title":"Complete a delegation","metric":"delegations_done","target":1,"reward":{"coins":15},"min_level":5,"weight":1,"status":"in_review"},{"id":"q_coach","title":"Finish a coaching call","metric":"coaching_calls","target":1,"reward":{"coins":20},"min_level":5,"weight":1,"status":"in_review"},{"id":"q_review","title":"Replay a call in review mode","metric":"review_replays","target":1,"reward":{"coins":5},"min_level":1,"weight":1,"status":"in_review"},{"id":"q_streak","title":"Keep your streak alive","metric":"streak_extended","target":1,"reward":{"coins":5},"min_level":1,"weight":1,"status":"in_review"}]'::jsonb,'Seed v1 (placeholder values until playtesting)',now());
