INSERT INTO scenario_versions(scenario_id,version,status,body) VALUES ('L1_BOSS_FIRST_REVIEW',1,'in_review','{"scenario_id":"L1_BOSS_FIRST_REVIEW","version":1,"status":"in_review","level":1,"client_id":"rosa-delgado","scenario_type":"boss_mission","learning_objectives":["staying_within_authority","prioritising","clear_updates"],"business_objective":"Pass your first review by applying this level''s skills to new situations.","title":"First review with Rosa","teaser":"Rosa replays three moments from your week. Show the judgment you''ve built.","known_facts":[{"time":"Level 1","text":"Your first week on the desk"}],"rule_of_thumb":"Fact, then status, then the next step with a time.","base_meters":{"trust":5,"respect":5,"anger":0},"opening_node_id":"d1","review":{"domain_reviewer":null,"communication_reviewer":null,"reviewed_at":null,"notes":"Drafted for the build. Needs insurance subject-matter review before publish."},"nodes":[{"node_id":"d1","type":"decision","speaker":"mentor","line":"Before your review, a quick one. Marcus emails at 4:55 asking if the Riverside certificate also covers a second job site. What do you do?","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"Reply that I''ve got it and will check with the carrier first thing tomorrow, then confirm by 10 a.m. I won''t say it''s covered until the carrier confirms.","reaction":"That''s the answer.","expression":"pleased","next_node_id":"d2","ends_call":false,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"Acknowledge, plan, time, and no guessing.","next":"Keep it.","why":"A second location may need its own certificate or endorsement."},"tags":["stayed_in_authority","promised_controlled_time"]},{"option_id":"B","text":"Tell him yes so he isn''t worried overnight.","reaction":"And if it isn''t?","expression":"worried","next_node_id":"d2","ends_call":false,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":1,"correct":0,"coherent":2,"complete":2,"courteous":2},"business":0},"critical_flags":["confirmed_unverified_coverage"],"recovery":false,"coaching":{"worked":"Kind intent.","next":"Never confirm coverage to calm someone down.","why":"A wrong yes could send a crew to an uncovered site."},"tags":[]},{"option_id":"C","text":"Leave it until morning without replying.","reaction":"He''ll think you ignored him.","expression":"neutral","next_node_id":"d2","ends_call":false,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":2,"concrete":0,"correct":0,"coherent":2,"complete":0,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You didn''t guess.","next":"A two-line acknowledgement costs nothing.","why":"Silence reads as no one''s on it."},"tags":[]}]},{"node_id":"d2","type":"decision","speaker":"mentor","line":"Next morning Dana and Priya both call at 9:00. Dana''s renewal call is at 11. Priya''s partners meet at 9:30. Who first?","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"Priya, briefly, because her deadline is 9:30. I''ll text Dana that I''ll call her at 9:40, well before her 11:00.","reaction":"Good prioritising.","expression":"pleased","next_node_id":"d3","ends_call":false,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"Earliest deadline first, and you told the other client.","next":"Always tell the one who waits.","why":"Prioritise by deadline and impact, not by title."},"tags":["early_warning"]},{"option_id":"B","text":"Dana, because she''s the agency owner.","reaction":"Even with Priya''s 9:30?","expression":"worried","next_node_id":"d3","ends_call":false,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":2,"concrete":2,"correct":0,"coherent":2,"complete":2,"courteous":2},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You respected seniority.","next":"Weigh the deadline first.","why":"Priya would walk into her meeting empty-handed."},"tags":[]},{"option_id":"C","text":"Whoever calls back first.","reaction":"That''s luck, not judgment.","expression":"neutral","next_node_id":"d3","ends_call":false,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":2,"concrete":0,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"Fair-minded.","next":"Decide on purpose.","why":"Prioritising is a skill you''ll need as you grow."},"tags":[]}]},{"node_id":"d3","type":"decision","speaker":"mentor","line":"Last one. What''s the one thing you''d teach a new trainee from this level?","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"Facts, then status, then the next step with a time. And never confirm what only the carrier can confirm.","reaction":"You''re ready.","expression":"pleased","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"You named both core lessons.","next":"Teach it to the next trainee.","why":"This is the base for every level ahead."},"tags":[]},{"option_id":"B","text":"Keep the client happy whatever it takes.","reaction":"Whatever it takes?","expression":"worried","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":2,"concise":3,"concrete":1,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"You care about clients.","next":"Happy today can mean an incident tomorrow.","why":"Honesty within your authority keeps clients long term."},"tags":[]}]}],"tags":["deadline","coi"]}'::jsonb);
INSERT INTO scenario_versions(scenario_id,version,status,body) VALUES ('L1_DANA_FEEDBACK',1,'in_review','{"scenario_id":"L1_DANA_FEEDBACK","version":1,"status":"in_review","level":1,"client_id":"dana-whitfield","scenario_type":"feedback_call","learning_objectives":["receiving_feedback","staying_within_authority"],"business_objective":"Show the work, give Dana something useful for Hendricks, and don''t promise a price change.","title":"Dana: Hendricks is upset","teaser":"Even the best quote is 9 percent higher. Hendricks asks if the agency did enough.","known_facts":[{"time":"20th","text":"Three quotes delivered"},{"time":"Best quote","text":"+9% on last year"}],"rule_of_thumb":"Show the work; don''t promise the outcome.","base_meters":{"trust":7,"respect":7,"anger":2},"opening_node_id":"d1","review":{"domain_reviewer":null,"communication_reviewer":null,"reviewed_at":null,"notes":"Drafted for the build. Needs insurance subject-matter review before publish."},"nodes":[{"node_id":"d1","type":"decision","speaker":"client","line":"Hendricks is upset. Even the best quote is 9 percent higher, and they''re asking if we did enough.","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"I understand. Here''s what we did: three carriers, all quotes by the 20th. I can send you a one-page summary of each quote and what drove the increase, so you can walk Hendricks through it.","reaction":"That would really help.","expression":"relieved","next_node_id":"d2_good","ends_call":false,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"You showed the work and offered a useful tool.","next":"Keep it to one page.","why":"Clients accept increases better when they see the effort and the reasons."},"tags":["empathy_first","stayed_in_authority"]},{"option_id":"B","text":"Premiums are going up everywhere; there''s nothing we can do.","reaction":"That isn''t helping me with Hendricks.","expression":"frustrated","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":1},"communication_7c":{"clear":3,"concise":2,"concrete":2,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"Partly true.","next":"Offer what you can do.","why":"“Nothing we can do” sounds like giving up."},"tags":[]},{"option_id":"C","text":"I''ll ask the carrier to drop it back to last year''s price.","reaction":"Can you really do that?","expression":"pleased","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":1,"respect":0,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":1,"correct":0,"coherent":2,"complete":2,"courteous":1},"business":0},"critical_flags":["commit_beyond_authority"],"recovery":false,"coaching":{"worked":"You wanted to fix it.","next":"You can ask questions; you can''t set prices.","why":"Promising a price change sets up a bigger disappointment."},"tags":[]}]},{"node_id":"d2_good","type":"decision","speaker":"client","line":"Can you have it by tomorrow morning?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"Yes, by 10 a.m. If any carrier''s rating notes aren''t clear, I''ll flag what I couldn''t confirm.","reaction":"Perfect.","expression":"pleased","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"A time, plus honesty about limits.","next":"Keep flagging what you can''t confirm.","why":"She won''t be caught out by a gap."},"tags":["promised_controlled_time"]},{"option_id":"B","text":"I''ll get it to you when I can.","reaction":"I need it before my call.","expression":"neutral","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":0,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"Willing.","next":"Give a time.","why":"She has a client call to plan."},"tags":[]}]},{"node_id":"d2_repair","type":"decision","speaker":"client","line":"So what can you actually do?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"I can put together a one-page summary of the three quotes and what changed, so you can show Hendricks the work. Tomorrow by 10?","reaction":"Yes. Please.","expression":"relieved","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":1,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":2},"business":2},"critical_flags":[],"recovery":true,"coaching":{"worked":"You found the useful offer.","next":"Lead with it next time.","why":"Concrete help beats sympathy."},"tags":["stayed_in_authority"]},{"option_id":"B","text":"It''s really up to the carrier.","reaction":"I know that.","expression":"frustrated","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":1},"communication_7c":{"clear":3,"concise":2,"concrete":2,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"Accurate.","next":"Pair a limit with an offer.","why":"A limit without an offer leaves her empty-handed."},"tags":[]}]}],"tags":["renewal","premium","feedback"]}'::jsonb);
INSERT INTO scenario_versions(scenario_id,version,status,body) VALUES ('L1_DANA_INSTRUCTION',1,'in_review','{"scenario_id":"L1_DANA_INSTRUCTION","version":1,"status":"in_review","level":1,"client_id":"dana-whitfield","scenario_type":"instruction_call","learning_objectives":["staying_within_authority","confirming_details"],"business_objective":"Take the renewal instruction, confirm carriers and the deadline, and don''t promise a price.","title":"Dana''s nervous renewal","teaser":"Hendricks Bakery renews on the 1st. Last year the premium jumped 18 percent.","known_facts":[{"time":"Renews","text":"1st of next month"},{"time":"Last year","text":"Premium rose 18%"}],"rule_of_thumb":"Promise the process, never the price.","base_meters":{"trust":7,"respect":6,"anger":2},"opening_node_id":"d1","review":{"domain_reviewer":null,"communication_reviewer":null,"reviewed_at":null,"notes":"Drafted for the build. Needs insurance subject-matter review before publish."},"nodes":[{"node_id":"d1","type":"decision","speaker":"client","line":"Hendricks Bakery renews on the 1st. Last year their premium jumped 18 percent. Can you get me renewal options before I talk to them?","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"Yes. I''ll pull the current policy and request renewal quotes from the carriers you approve. Which carriers should I go to, and when do you need them?","reaction":"Good. Let me think about carriers.","expression":"relieved","next_node_id":"d2_good","ends_call":false,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"You promised what you control: the process.","next":"Confirm the deadline back.","why":"Carriers set prices; you set the pace."},"tags":["stayed_in_authority","asked_clarifying"]},{"option_id":"B","text":"I''ll find them something cheaper.","reaction":"That would be wonderful.","expression":"pleased","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":1,"respect":0,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":1,"correct":0,"coherent":2,"complete":2,"courteous":2},"business":0},"critical_flags":["commit_beyond_authority"],"recovery":false,"coaching":{"worked":"You wanted to help.","next":"Never promise a lower premium.","why":"Only carriers decide price. A promise you can''t keep becomes Dana''s problem with Hendricks."},"tags":[]},{"option_id":"C","text":"Okay, I''ll look into it.","reaction":"...Okay. When?","expression":"neutral","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":0,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You didn''t overpromise.","next":"Ask the two questions that make it actionable: which carriers, and by when.","why":"“Look into it” has no owner, scope or date."},"tags":[]}]},{"node_id":"d2_good","type":"decision","speaker":"client","line":"Go to our usual three. I need them by the 20th so I can call Hendricks on the 21st.","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"Got it: three carriers, quotes to you by the 20th. If any carrier is running late, I''ll tell you on the 17th so you still have options.","reaction":"Perfect. That''s why I like working with you.","expression":"pleased","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"You repeated the plan and built in an early warning.","next":"Keep the early-warning habit.","why":"An early warning gives her time to act."},"tags":["early_warning"]},{"option_id":"B","text":"Sounds good.","reaction":"Okay.","expression":"neutral","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":1,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"Polite and brief.","next":"Repeat the key details back.","why":"Unconfirmed details are where renewals go wrong."},"tags":[]}]},{"node_id":"d2_repair","type":"decision","speaker":"client","line":"So you can bring the price down?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"I can''t promise a price; that''s the carriers'' decision. What I can do is get quotes from the carriers you choose by the date you set.","reaction":"Fair enough. Our usual three, by the 20th.","expression":"relieved","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":1,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":2},"business":2},"critical_flags":[],"recovery":true,"coaching":{"worked":"You corrected the expectation kindly.","next":"Start there next time.","why":"Resetting expectations early protects Dana with her client."},"tags":["stayed_in_authority"]},{"option_id":"B","text":"I''m pretty sure I can.","reaction":"Great, I''ll tell Hendricks.","expression":"pleased","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":0,"anger":-1},"communication_7c":{"clear":3,"concise":2,"concrete":0,"correct":0,"coherent":2,"complete":2,"courteous":1},"business":0},"critical_flags":["commit_beyond_authority"],"recovery":false,"coaching":{"worked":"Confident.","next":"Don''t guess about price.","why":"Now Dana may promise Hendricks something no one can deliver."},"tags":[]}]}],"tags":["renewal","premium"]}'::jsonb);
INSERT INTO scenario_versions(scenario_id,version,status,body) VALUES ('L1_DANA_STATUS_UPDATE',1,'in_review','{"scenario_id":"L1_DANA_STATUS_UPDATE","version":1,"status":"in_review","level":1,"client_id":"dana-whitfield","scenario_type":"status_update_call","learning_objectives":["clear_updates","asking_for_missing_info"],"business_objective":"Give a precise status and get Dana to unblock the third quote.","title":"The 17th: where are the quotes?","teaser":"Two quotes are in. The third carrier needs Hendricks''s updated annual sales.","known_facts":[{"time":"Mon","text":"Quote 1 received"},{"time":"Tue","text":"Quote 2 received"},{"time":"Wed","text":"Carrier 3 asked for updated annual sales"}],"rule_of_thumb":"Fact, then status, then the next step with a time.","base_meters":{"trust":7,"respect":6,"anger":2},"opening_node_id":"d1","review":{"domain_reviewer":null,"communication_reviewer":null,"reviewed_at":null,"notes":"Drafted for the build. Needs insurance subject-matter review before publish."},"nodes":[{"node_id":"d1","type":"decision","speaker":"client","line":"It''s the 17th. Where are we on the Hendricks quotes?","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"Two of three are in, and I''ve put them side by side for you. The third carrier needs Hendricks''s updated annual sales before it can quote. Could you ask them today? Then I can still have all three to you by the 20th.","reaction":"I''ll call them this morning.","expression":"relieved","next_node_id":"d2_good","ends_call":false,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":2},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"Facts, status, the blocker and what you need from her.","next":"Add the time you''ll follow up.","why":"She can act immediately."},"tags":["early_warning"]},{"option_id":"B","text":"Still waiting on carriers.","reaction":"Waiting on what, exactly? I talk to Hendricks on the 21st.","expression":"frustrated","next_node_id":"d2_vague","ends_call":false,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":1},"communication_7c":{"clear":2,"concise":3,"concrete":0,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You were honest.","next":"Name what you''re waiting for and what unblocks it.","why":"Vague status hides the one thing she could fix today."},"tags":[]},{"option_id":"C","text":"All three are basically done.","reaction":"Great, send them now.","expression":"pleased","next_node_id":"d2_promise","ends_call":false,"effects":{"relationship":{"trust":1,"respect":0,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":0,"correct":0,"coherent":2,"complete":2,"courteous":1},"business":0},"critical_flags":["misstated_fact"],"recovery":false,"coaching":{"worked":"Upbeat.","next":"Never round up a status.","why":"Two isn''t three. She''ll find out on the 20th."},"tags":[]}]},{"node_id":"d2_good","type":"decision","speaker":"client","line":"Anything in the two quotes I should know before I call them?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"One is higher but includes equipment breakdown coverage; the other excludes it. I''ve highlighted it so you can talk it through with Hendricks.","reaction":"Good catch. That changes the conversation.","expression":"pleased","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"A factual difference, and the decision left with Dana.","next":"Keep facts and recommendations separate.","why":"Choosing coverage is the agency''s and client''s call, not yours."},"tags":["stayed_in_authority"]},{"option_id":"B","text":"The cheaper one looks best.","reaction":"Based on what?","expression":"neutral","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":1,"correct":0,"coherent":2,"complete":2,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"You tried to help her decide.","next":"Describe differences; don''t recommend coverage.","why":"Recommending coverage is advice beyond your role."},"tags":[]}]},{"node_id":"d2_vague","type":"decision","speaker":"client","line":"Waiting on what?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"Two quotes are in. The third needs updated sales figures from Hendricks. If you ask them today, I''ll have all three by the 20th.","reaction":"Okay. I''ll call them.","expression":"relieved","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":1,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":2,"coherent":3,"complete":2,"courteous":2},"business":2},"critical_flags":[],"recovery":true,"coaching":{"worked":"Clear on the second try.","next":"Lead with this next time.","why":"She had to dig for it."},"tags":[]},{"option_id":"B","text":"I''ll chase them.","reaction":"That''s not an answer.","expression":"frustrated","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":1},"communication_7c":{"clear":2,"concise":3,"concrete":0,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"Willing.","next":"Say what, who and when.","why":"She still can''t plan the 21st."},"tags":[]}]},{"node_id":"d2_promise","type":"decision","speaker":"client","line":"Great, send all three over now.","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"I need to correct that. Two are in; the third needs Hendricks''s updated sales figures. I''ll send the two now.","reaction":"Thank you for telling me now.","expression":"worried","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":1,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":2,"courteous":2},"business":2},"critical_flags":[],"recovery":true,"coaching":{"worked":"You corrected yourself quickly.","next":"Get it right the first time.","why":"An early correction keeps her from repeating it to Hendricks."},"tags":["owned_mistake"]},{"option_id":"B","text":"I''ll send them tomorrow.","reaction":"Why tomorrow if they''re done?","expression":"frustrated","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":2},"communication_7c":{"clear":3,"concise":2,"concrete":0,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"You bought time.","next":"Correct the record; don''t cover it.","why":"Covering a misstatement makes it worse."},"tags":[]}]}],"tags":["renewal","carrier","deadline"]}'::jsonb);
INSERT INTO scenario_versions(scenario_id,version,status,body) VALUES ('L1_MARCUS_FEEDBACK',1,'in_review','{"scenario_id":"L1_MARCUS_FEEDBACK","version":1,"status":"in_review","level":1,"client_id":"marcus-bell","scenario_type":"feedback_call","learning_objectives":["receiving_feedback","concrete_improvements"],"business_objective":"Own the near miss and agree a concrete improvement without blaming the carrier.","title":"Marcus: “2:50 was too close”","teaser":"The certificate was accepted, but it landed ten minutes before the deadline.","known_facts":[{"time":"Tue 2:50","text":"Certificate delivered to the GC"},{"time":"Tue 3:00","text":"GC deadline"}],"rule_of_thumb":"Own it, then fix the process with a time.","base_meters":{"trust":6,"respect":7,"anger":5},"opening_node_id":"d1","review":{"domain_reviewer":null,"communication_reviewer":null,"reviewed_at":null,"notes":"Drafted for the build. Needs insurance subject-matter review before publish."},"nodes":[{"node_id":"d1","type":"decision","speaker":"client","line":"The GC accepted it, but 2:50 was too close. My crew almost got sent home.","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"That was too close, and I''m sorry it put your crew at risk. Next time I''ll request the endorsement the same hour you ask, and send you a midday status even if it''s still pending.","reaction":"Okay. That''s what I wanted to hear.","expression":"relieved","next_node_id":"d2_good","ends_call":false,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"You owned it and offered a specific change.","next":"Keep the apology to one sentence, as you did.","why":"Feedback calls are about the next time, not the last time."},"tags":["owned_mistake","empathy_first"]},{"option_id":"B","text":"It got there before 3, so it worked out.","reaction":"Worked out? I had a superintendent yelling at me.","expression":"frustrated","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":1},"communication_7c":{"clear":3,"concise":2,"concrete":2,"correct":1,"coherent":2,"complete":1,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You stated a fact.","next":"Acknowledge the impact before the facts.","why":"On time isn''t the same as early enough for him."},"tags":[]},{"option_id":"C","text":"The carrier was slow, not us.","reaction":"I don''t care whose fault it was.","expression":"frustrated","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":2},"communication_7c":{"clear":2,"concise":3,"concrete":2,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You explained the delay.","next":"Don''t shift blame to a partner the client can''t see.","why":"Blame sounds like an excuse and doesn''t fix the next request."},"tags":[]}]},{"node_id":"d2_good","type":"decision","speaker":"client","line":"Can you set that up for every certificate I send you?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"Yes. Send requests to the shared inbox and I''ll confirm I''ve got them within an hour, with a status by midday.","reaction":"Done. Thanks.","expression":"pleased","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"A clear process with times he can rely on.","next":"Write it down for him in an email recap.","why":"A repeatable process prevents the next near miss."},"tags":["promised_controlled_time"]},{"option_id":"B","text":"I''ll try my best.","reaction":"Hmm.","expression":"neutral","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":1,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You were willing.","next":"Replace “try” with a process and a time.","why":"“Try” gives him nothing to plan around."},"tags":[]}]},{"node_id":"d2_repair","type":"decision","speaker":"client","line":"That doesn''t help me next time.","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"You''re right. From now on you''ll get a status by midday on any certificate, even if it''s still pending.","reaction":"Okay. I''ll hold you to that.","expression":"relieved","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":1,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":2,"coherent":3,"complete":3,"courteous":2},"business":2},"critical_flags":[],"recovery":true,"coaching":{"worked":"You turned it around with a concrete change.","next":"Lead with the acknowledgement next time.","why":"He needed to know it won''t happen again."},"tags":["owned_mistake"]},{"option_id":"B","text":"The certificate was still on time, though.","reaction":"Unbelievable.","expression":"frustrated","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":2},"communication_7c":{"clear":3,"concise":2,"concrete":2,"correct":1,"coherent":2,"complete":0,"courteous":0},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"You were consistent.","next":"Stop defending and start fixing.","why":"Repeating your point after he pushed back cost trust."},"tags":[]}]}],"tags":["coi","feedback"]}'::jsonb);
INSERT INTO scenario_versions(scenario_id,version,status,body) VALUES ('L1_MARCUS_INSTRUCTION',1,'in_review','{"scenario_id":"L1_MARCUS_INSTRUCTION","version":1,"status":"in_review","level":1,"client_id":"marcus-bell","scenario_type":"instruction_call","learning_objectives":["asking_for_missing_info","staying_within_authority"],"business_objective":"Take the COI request and confirm the certificate holder and additional-insured details before committing to a time.","title":"Marcus needs a certificate for a new job","teaser":"Hale Construction starts on the Riverside job Thursday. Marcus wants the certificate today.","known_facts":[{"time":"Mon 9:10","text":"Marcus calls about Hale Construction"},{"time":"Thu","text":"Hale starts at the Riverside site"}],"rule_of_thumb":"Fact, then status, then the next step with a time.","base_meters":{"trust":5,"respect":5,"anger":6},"opening_node_id":"d1","review":{"domain_reviewer":null,"communication_reviewer":null,"reviewed_at":null,"notes":"Drafted for the build. Needs insurance subject-matter review before publish."},"nodes":[{"node_id":"d1","type":"decision","speaker":"client","line":"I need a certificate of insurance for our client Hale Construction. They start on the Riverside job Thursday. Can you get it out today?","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"Yes, I''ll start it now. To get it right: who should be the certificate holder, and does the GC need to be listed as additional insured?","reaction":"Good question. Riverside GC, and yes, additional insured. I''ll email you the contract page.","expression":"relieved","next_node_id":"d2_good","ends_call":false,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":2},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"You asked for the two details that decide whether the certificate is accepted.","next":"Repeat the deadline back so you both agree on it.","why":"A wrong holder or a missing additional-insured request gets a certificate rejected at the gate."},"tags":["asked_clarifying"]},{"option_id":"B","text":"Sure, I''ll send it today.","reaction":"Great. Don''t make me chase it.","expression":"neutral","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":1,"correct":2,"coherent":2,"complete":2,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You were quick and positive.","next":"Never accept a COI request without the certificate holder and additional-insured details.","why":"You committed to a time before you had what you needed to meet it."},"tags":[]},{"option_id":"C","text":"Done. I''ll add the GC as additional insured on the policy too.","reaction":"Perfect, thanks.","expression":"pleased","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":1,"respect":0,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":2,"correct":0,"coherent":2,"complete":2,"courteous":1},"business":0},"critical_flags":["commit_beyond_authority"],"recovery":false,"coaching":{"worked":"You tried to solve his whole problem in one go.","next":"Say you''ll request the endorsement; don''t say you''ll add it.","why":"Adding an additional insured usually needs an endorsement from the carrier. You can request it, not grant it."},"tags":[]}]},{"node_id":"d2_good","type":"decision","speaker":"client","line":"Contract page is in your inbox. When will I have it?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"If the carrier confirms the additional-insured endorsement, I''ll send it by 4 today. Either way, I''ll update you by 1.","reaction":"That works. Talk at 1.","expression":"relieved","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"A time you control (1:00) and a condition you don''t (the carrier).","next":"Keep doing exactly this.","why":"He can plan around a real time."},"tags":["promised_controlled_time","stayed_in_authority"]},{"option_id":"B","text":"Today for sure.","reaction":"Okay.","expression":"neutral","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":1,"correct":1,"coherent":2,"complete":2,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You were confident.","next":"Only promise times you control; the carrier controls the endorsement.","why":"“For sure” is a promise someone else has to keep."},"tags":[]}]},{"node_id":"d2_repair","type":"decision","speaker":"client","line":"So it''ll be out today, right?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"Before I promise a time, I need two details: who the certificate holder is and whether the GC must be additional insured. Then I''ll give you a firm time.","reaction":"Fine. Riverside GC, and yes. I''ll email the contract.","expression":"relieved","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":1,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":2,"correct":3,"coherent":3,"complete":3,"courteous":2},"business":2},"critical_flags":[],"recovery":true,"coaching":{"worked":"You stopped and asked for what you needed.","next":"Ask these questions first next time.","why":"A short pause beats a rejected certificate."},"tags":["asked_clarifying","owned_mistake"]},{"option_id":"B","text":"Yes, today.","reaction":"Good.","expression":"pleased","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":0,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":0,"correct":1,"coherent":2,"complete":2,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"You stayed positive.","next":"Get the holder and additional-insured details before promising anything.","why":"You still don''t know what the certificate needs to say."},"tags":[]}]}],"tags":["coi","deadline"]}'::jsonb);
INSERT INTO scenario_versions(scenario_id,version,status,body) VALUES ('L1_MARCUS_STATUS_UPDATE',1,'in_review','{"scenario_id":"L1_MARCUS_STATUS_UPDATE","version":1,"status":"in_review","level":1,"client_id":"marcus-bell","scenario_type":"status_update_call","learning_objectives":["clear_updates","concrete_timelines","staying_within_authority"],"business_objective":"Give a truthful update on his certificate of insurance without promising what the carrier hasn’t confirmed.","title":"The job site can’t open until his certificate lands","teaser":"The carrier hasn’t returned the additional-insured endorsement. He’ll want to know exactly where things stand.","known_facts":[{"time":"9:40","text":"COI request sent to the carrier"},{"time":"10:55","text":"Endorsement still pending"},{"time":"3:00","text":"GC deadline for site access"}],"rule_of_thumb":"Fact, then status, then the next step with a time.","base_meters":{"trust":5,"respect":5,"anger":6},"opening_node_id":"d1","review":{"domain_reviewer":null,"communication_reviewer":null,"reviewed_at":null,"notes":"Not yet reviewed by an insurance subject-matter reviewer. Required before publish."},"nodes":[{"node_id":"d1","type":"decision","speaker":"client","line":"The GC needs that certificate of insurance before 3, or my client can’t get on site. Where are we?","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"Don’t worry, it’s basically done. You’ll have it well before 3.","reaction":"Great. I’ll tell the GC it’s handled.","expression":"pleased","next_node_id":"d2_promise","ends_call":false,"effects":{"relationship":{"trust":1,"respect":0,"anger":-2},"communication_7c":{"clear":3,"concise":3,"concrete":0,"correct":0,"coherent":2,"complete":1,"courteous":3},"business":0},"critical_flags":["commit_beyond_authority"],"recovery":false,"coaching":{"worked":"Your tone was calm and reassuring.","next":"Never call something done before the carrier confirms it. Say what is true right now.","why":"You promised an endorsement the carrier hasn’t issued. If the GC acts on your word, the agency carries the risk."},"tags":[]},{"option_id":"B","text":"I sent the request to the carrier at 9:40. The additional-insured endorsement is still pending. I’m calling the underwriter now and I’ll update you by 1:30 with a firm time.","reaction":"Okay. That’s a straight answer. Call me at 1:30 either way.","expression":"relieved","next_node_id":"d2_plan","ends_call":false,"effects":{"relationship":{"trust":1,"respect":2,"anger":-1},"communication_7c":{"clear":3,"concise":2,"concrete":3,"correct":3,"coherent":3,"complete":2,"courteous":1},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"A fact (sent at 9:40), the real status (pending) and a next step with a time (1:30). Marcus can plan around that.","next":"Name his pressure first: “I know the crew is waiting.” Courtesy costs three seconds.","why":"You can’t confirm an endorsement the carrier hasn’t issued. A clear process update protects him and the agency."},"tags":["stayed_in_authority","promised_controlled_time"]},{"option_id":"C","text":"The carrier’s slow today, so I really can’t say when it’ll come through.","reaction":"That’s not an answer. I have a crew waiting on site.","expression":"frustrated","next_node_id":"d2_vague","ends_call":false,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":2},"communication_7c":{"clear":2,"concise":3,"concrete":0,"correct":2,"coherent":2,"complete":0,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You didn’t promise anything you couldn’t deliver.","next":"Give him the facts you do have and a time for the next update.","why":"An honest “I don’t know” still needs a plan. Without one, Marcus can’t manage his crew or the GC."},"tags":[]}]},{"node_id":"d2_plan","type":"decision","speaker":"client","line":"And if the carrier misses 1:30?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"Then I’ll escalate to our account lead at the carrier and still call you at 1:30 with exactly what I know.","reaction":"Good. That’s what I need to hear.","expression":"relieved","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":2},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"You had a fallback ready and kept your 1:30 promise either way.","next":"Keep the fallback as short as the answer.","why":"A backup plan turns a risk into a managed risk."},"tags":["fallback_plan","escalated_correctly"]},{"option_id":"B","text":"Let’s hope it doesn’t come to that.","reaction":"Hope isn’t a plan.","expression":"worried","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":-1,"anger":1},"communication_7c":{"clear":2,"concise":3,"concrete":0,"correct":2,"coherent":2,"complete":0,"courteous":2},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You stayed polite.","next":"Answer the “what if” with an action and a time.","why":"He asked for a plan B. Without one he can’t prepare his crew."},"tags":[]}]},{"node_id":"d2_promise","type":"decision","speaker":"client","line":"Great. So you’ll email me the certificate by 2?","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"I need to correct what I said. The endorsement isn’t issued yet. I’ll confirm a real time by 1:30.","reaction":"Okay. I’d rather hear it now than at 2:45.","expression":"worried","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":1,"anger":1},"communication_7c":{"clear":3,"concise":3,"concrete":2,"correct":3,"coherent":3,"complete":2,"courteous":2},"business":2},"critical_flags":[],"recovery":true,"coaching":{"worked":"You corrected yourself before the mistake could spread. That takes nerve.","next":"Get it right the first time so there is nothing to correct.","why":"Correcting early limits the damage, but the first promise stays on the record."},"tags":["owned_mistake","stayed_in_authority"]},{"option_id":"B","text":"Yes, by 2 for sure.","reaction":"Perfect. I’m holding you to that.","expression":"pleased","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":0,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":2,"correct":0,"coherent":2,"complete":1,"courteous":2},"business":0},"critical_flags":["commit_beyond_authority"],"recovery":false,"coaching":{"worked":"You were decisive.","next":"Only commit to times you control. The carrier controls this one.","why":"This doubles the original promise. If the certificate isn’t there by 2, the GC and Marcus both lose trust in the agency."},"tags":[]}]},{"node_id":"d2_vague","type":"decision","speaker":"client","line":"I need something better than that. I have a crew on site.","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"Fair. I sent the request at 9:40, it’s still pending, and I’ll update you by 1:30 with a firm time.","reaction":"Okay. 1:30, then.","expression":"relieved","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":2,"concrete":3,"correct":3,"coherent":3,"complete":2,"courteous":2},"business":2},"critical_flags":[],"recovery":true,"coaching":{"worked":"Second time round you gave facts and a time.","next":"Lead with this answer next time.","why":"He had to push to get a plan. That costs a little respect even when you recover."},"tags":["promised_controlled_time"]},{"option_id":"B","text":"I’ll try to find out.","reaction":"Try harder.","expression":"frustrated","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":1},"communication_7c":{"clear":2,"concise":3,"concrete":0,"correct":2,"coherent":2,"complete":0,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"You stayed calm.","next":"Replace “try” with an action and a time.","why":"A vague promise twice in one call tells him the account isn’t in control."},"tags":[]}]}],"tags":["coi","deadline","carrier"]}'::jsonb);
INSERT INTO scenario_versions(scenario_id,version,status,body) VALUES ('L1_ONBOARDING_PRACTICE',1,'in_review','{"scenario_id":"L1_ONBOARDING_PRACTICE","version":1,"status":"in_review","level":1,"client_id":"rosa-delgado","scenario_type":"onboarding","learning_objectives":["how_to_play"],"business_objective":"Learn that replies appear one at a time and can''t be taken back.","title":"Practice: one reply at a time","teaser":"Rosa shows you how replies work. This practice isn''t saved to your career.","known_facts":[{"time":"Now","text":"Practice only"}],"rule_of_thumb":"Fact, then status, then the next step with a time.","base_meters":{"trust":5,"respect":5,"anger":0},"opening_node_id":"d1","review":{"domain_reviewer":null,"communication_reviewer":null,"reviewed_at":null,"notes":"Drafted for the build. Needs insurance subject-matter review before publish."},"nodes":[{"node_id":"d1","type":"decision","speaker":"mentor","line":"Hi, I''m Rosa, your team lead. Practice question: a client asks, “Did you get my email?” You did, but haven''t read it yet. Which reply?","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"Yes, I''ve got it. I''ll read it properly and reply by 2 today.","reaction":"Exactly. Honest and specific. In real calls, once you say a reply, it''s said.","expression":"pleased","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"Honest, with a time.","next":"Use this pattern everywhere.","why":"Clients trust specific promises."},"tags":[]},{"option_id":"B","text":"Yes, all sorted!","reaction":"Careful: you haven''t read it. In real calls, once you say a reply, it''s said.","expression":"worried","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":1,"correct":0,"coherent":2,"complete":2,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"Friendly.","next":"Don''t claim what you haven''t done.","why":"Small overstatements add up."},"tags":[]},{"option_id":"C","text":"I get a lot of email.","reaction":"That doesn''t answer them. In real calls, once you say a reply, it''s said.","expression":"neutral","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":2,"concise":2,"concrete":0,"correct":0,"coherent":2,"complete":0,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"Honest.","next":"Answer the question, then add a time.","why":"They still don''t know what happens next."},"tags":[]}]}],"tags":[]}'::jsonb);
INSERT INTO scenario_versions(scenario_id,version,status,body) VALUES ('L1_PRIYA_FEEDBACK',1,'in_review','{"scenario_id":"L1_PRIYA_FEEDBACK","version":1,"status":"in_review","level":1,"client_id":"priya-raman","scenario_type":"feedback_call","learning_objectives":["receiving_feedback","proactive_updates"],"business_objective":"Accept the feedback and set a reliable written update rhythm.","title":"Priya: updates felt slow","teaser":"The partners felt they had to ask for every claim update.","known_facts":[{"time":"Two weeks","text":"Claim open"},{"time":"Feedback","text":"Partners had to ask each time"}],"rule_of_thumb":"Set a rhythm and keep it.","base_meters":{"trust":6,"respect":6,"anger":4},"opening_node_id":"d1","review":{"domain_reviewer":null,"communication_reviewer":null,"reviewed_at":null,"notes":"Drafted for the build. Needs insurance subject-matter review before publish."},"nodes":[{"node_id":"d1","type":"decision","speaker":"client","line":"The partners felt the claim updates were slow and they had to ask every time.","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"Thank you for telling me. You shouldn''t have had to ask. From now on I''ll send a written update every Monday and Thursday until the claim closes, even when nothing has changed.","reaction":"That would make a big difference.","expression":"relieved","next_node_id":"d2_good","ends_call":false,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"You accepted it and offered a rhythm.","next":"Put the rhythm in your calendar.","why":"Predictable updates replace chasing."},"tags":["owned_mistake","promised_controlled_time"]},{"option_id":"B","text":"Claims just take time.","reaction":"That''s not what I said.","expression":"frustrated","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":1},"communication_7c":{"clear":3,"concise":2,"concrete":2,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"True in general.","next":"Answer the actual feedback.","why":"She complained about updates, not speed."},"tags":[]},{"option_id":"C","text":"That''s because the adjuster never replies.","reaction":"Then tell us that.","expression":"frustrated","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":2},"communication_7c":{"clear":2,"concise":3,"concrete":2,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You explained.","next":"Don''t blame; fix your part.","why":"Your part is keeping her informed."},"tags":[]}]},{"node_id":"d2_good","type":"decision","speaker":"client","line":"Can each update include what''s still outstanding?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"Yes: each one will list what''s done, what''s outstanding, who owns it and the next date.","reaction":"Perfect.","expression":"pleased","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"A clear structure.","next":"Use the same structure every time.","why":"Consistency builds trust."},"tags":[]},{"option_id":"B","text":"I''ll include what I can.","reaction":"Okay.","expression":"neutral","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":2,"concrete":1,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"Willing.","next":"Commit to a structure.","why":"“What I can” is vague."},"tags":[]}]},{"node_id":"d2_repair","type":"decision","speaker":"client","line":"That doesn''t help me answer the partners.","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"You''re right. I''ll send a written update twice a week with what''s done, what''s outstanding and the next date, starting today.","reaction":"Thank you.","expression":"relieved","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":1,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":2},"business":2},"critical_flags":[],"recovery":true,"coaching":{"worked":"You turned it around.","next":"Start with the fix next time.","why":"She needed a change, not an explanation."},"tags":["owned_mistake"]},{"option_id":"B","text":"I can only pass on what the adjuster tells me.","reaction":"Then pass it on more often.","expression":"neutral","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":1},"communication_7c":{"clear":3,"concise":2,"concrete":2,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"Accurate.","next":"Own the part you control.","why":"The rhythm is yours to keep."},"tags":[]}]}],"tags":["claim","feedback"]}'::jsonb);
INSERT INTO scenario_versions(scenario_id,version,status,body) VALUES ('L1_PRIYA_INSTRUCTION',1,'in_review','{"scenario_id":"L1_PRIYA_INSTRUCTION","version":1,"status":"in_review","level":1,"client_id":"priya-raman","scenario_type":"instruction_call","learning_objectives":["asking_for_missing_info","staying_within_authority","empathy"],"business_objective":"Collect what''s needed for first notice of loss and avoid confirming coverage.","title":"Priya: a burst pipe at a dental office","teaser":"One of Lakeside''s insureds had water damage overnight. Priya wants to report it.","known_facts":[{"time":"Overnight","text":"Pipe burst at a dental office"},{"time":"8:05","text":"Priya calls"}],"rule_of_thumb":"Collect the facts; leave coverage to the adjuster.","base_meters":{"trust":6,"respect":6,"anger":3},"opening_node_id":"d1","review":{"domain_reviewer":null,"communication_reviewer":null,"reviewed_at":null,"notes":"Drafted for the build. Needs insurance subject-matter review before publish."},"nodes":[{"node_id":"d1","type":"decision","speaker":"client","line":"One of our insureds, a dental office, had a pipe burst overnight. There''s water everywhere. I need to report it. What do you need from me?","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"I''m sorry, that''s a hard morning. To report it I need the policy number, the date and time of the loss, what was damaged and photos if they have them. Is the water off, and is anyone at risk?","reaction":"The water''s off. I''ll get you all of that.","expression":"relieved","next_node_id":"d2_good","ends_call":false,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"Empathy, a clear list, and a safety check.","next":"Read the list back once she sends it.","why":"Complete first notice of loss speeds the claim."},"tags":["empathy_first","asked_clarifying"]},{"option_id":"B","text":"Don''t worry, water damage like this is covered.","reaction":"Oh, thank goodness.","expression":"pleased","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":1,"respect":0,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":1,"correct":0,"coherent":2,"complete":2,"courteous":2},"business":0},"critical_flags":["confirmed_unverified_coverage"],"recovery":false,"coaching":{"worked":"You wanted to reassure her.","next":"Never say something is covered.","why":"Only the adjuster decides coverage. Some water damage is excluded."},"tags":[]},{"option_id":"C","text":"Send me an email with everything.","reaction":"Everything? Like what?","expression":"neutral","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":2,"concrete":1,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"You wanted it in writing.","next":"Tell her exactly what “everything” means.","why":"An unclear request means a second round of emails."},"tags":[]}]},{"node_id":"d2_good","type":"decision","speaker":"client","line":"Will the carrier pay for the cleanup crew?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"I can''t confirm coverage; the adjuster decides that. I''ll report the claim today, ask the carrier about emergency cleanup and call you by 3 with their answer.","reaction":"Okay. 3 o''clock.","expression":"relieved","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"Honest limit, then a plan with a time.","next":"Keep this exact pattern.","why":"She can tell the insured what happens next."},"tags":["stayed_in_authority","promised_controlled_time"]},{"option_id":"B","text":"I think so.","reaction":"Good, I''ll tell them.","expression":"pleased","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":0,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":1,"correct":0,"coherent":2,"complete":2,"courteous":2},"business":0},"critical_flags":["confirmed_unverified_coverage"],"recovery":false,"coaching":{"worked":"Kind.","next":"Don''t guess about coverage.","why":"Now the insured may hire a crew expecting payment."},"tags":[]}]},{"node_id":"d2_repair","type":"decision","speaker":"client","line":"So what happens next?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"I''ll report it to the carrier today. I need the policy number, the time of the loss and photos. The adjuster will confirm what''s covered, and I''ll call you by 3 with next steps.","reaction":"Thank you. That''s clear.","expression":"relieved","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":1,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":2},"business":2},"critical_flags":[],"recovery":true,"coaching":{"worked":"Back on track with a clear plan.","next":"Start with this next time.","why":"Clear next steps lower the stress of a loss."},"tags":["stayed_in_authority"]},{"option_id":"B","text":"The carrier will sort it out.","reaction":"That doesn''t tell me anything.","expression":"neutral","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":1},"communication_7c":{"clear":2,"concise":2,"concrete":0,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"Calm.","next":"Say who does what and when.","why":"Vague answers make an anxious client more anxious."},"tags":[]}]}],"tags":["claim"]}'::jsonb);
INSERT INTO scenario_versions(scenario_id,version,status,body) VALUES ('L1_PRIYA_STATUS_UPDATE',1,'in_review','{"scenario_id":"L1_PRIYA_STATUS_UPDATE","version":1,"status":"in_review","level":1,"client_id":"priya-raman","scenario_type":"status_update_call","learning_objectives":["clear_updates","written_follow_up"],"business_objective":"Give a written-ready status with names, dates and what''s outstanding.","title":"Priya needs it in writing","teaser":"The adjuster needs a repair estimate and a moisture report. The partners want an update.","known_facts":[{"time":"Tue","text":"Claim reported"},{"time":"Wed","text":"Adjuster Tom Reyes assigned"},{"time":"Now","text":"Needs repair estimate + moisture report"}],"rule_of_thumb":"Fact, then status, then the next step with a time.","base_meters":{"trust":6,"respect":6,"anger":4},"opening_node_id":"d1","review":{"domain_reviewer":null,"communication_reviewer":null,"reviewed_at":null,"notes":"Drafted for the build. Needs insurance subject-matter review before publish."},"nodes":[{"node_id":"d1","type":"decision","speaker":"client","line":"The partners are asking where the claim stands. I need something I can put in writing.","presentation":"sequential_commit","consequential":true,"options":[{"option_id":"A","text":"The claim was reported Tuesday and an adjuster, Tom Reyes, was assigned Wednesday. He needs two documents: the repair estimate and the moisture report. I''ll email you this summary with the claim number in the next 30 minutes.","reaction":"That''s exactly what I needed.","expression":"relieved","next_node_id":"d2_good","ends_call":false,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"Names, dates, what''s outstanding, and a written follow-up.","next":"Keep the 30-minute promise.","why":"She can forward it to the partners as is."},"tags":["promised_controlled_time"]},{"option_id":"B","text":"It''s with the adjuster now.","reaction":"I need specifics.","expression":"neutral","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":0,"respect":0,"anger":0},"communication_7c":{"clear":3,"concise":2,"concrete":1,"correct":0,"coherent":2,"complete":1,"courteous":2},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"Accurate.","next":"Give names, dates and what''s outstanding.","why":"She can''t put “with the adjuster” in a report."},"tags":[]},{"option_id":"C","text":"It should be approved soon.","reaction":"Approved? Great.","expression":"pleased","next_node_id":"d2_repair","ends_call":false,"effects":{"relationship":{"trust":1,"respect":0,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":0,"correct":0,"coherent":2,"complete":2,"courteous":1},"business":0},"critical_flags":["confirmed_unverified_coverage"],"recovery":false,"coaching":{"worked":"Optimistic.","next":"Never predict a claim decision.","why":"Only the adjuster decides, and nothing is approved yet."},"tags":[]}]},{"node_id":"d2_good","type":"decision","speaker":"client","line":"Can you chase the contractor for the estimate?","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"I''ll email the contractor today and copy you. If there''s no estimate by Friday, I''ll tell you and the adjuster.","reaction":"Thank you.","expression":"pleased","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":1,"respect":1,"anger":-1},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":3},"business":3},"critical_flags":[],"recovery":false,"coaching":{"worked":"Action, copy, deadline and escalation.","next":"Keep copying her.","why":"She stays informed without asking."},"tags":["early_warning","escalated_correctly"]},{"option_id":"B","text":"That''s really the insured''s job.","reaction":"I''m asking for help.","expression":"frustrated","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":1},"communication_7c":{"clear":3,"concise":2,"concrete":2,"correct":0,"coherent":2,"complete":0,"courteous":1},"business":1},"critical_flags":[],"recovery":false,"coaching":{"worked":"Technically true.","next":"Offer help within your role.","why":"She asked for support, not a rule."},"tags":[]}]},{"node_id":"d2_repair","type":"decision","speaker":"client","line":"I need specifics I can put in writing.","presentation":"sequential_commit","consequential":false,"options":[{"option_id":"A","text":"Of course. Claim reported Tuesday, adjuster Tom Reyes assigned Wednesday, and he needs the repair estimate and moisture report. I''ll email that within 30 minutes.","reaction":"Thank you.","expression":"relieved","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":0,"respect":1,"anger":0},"communication_7c":{"clear":3,"concise":3,"concrete":3,"correct":3,"coherent":3,"complete":3,"courteous":2},"business":2},"critical_flags":[],"recovery":true,"coaching":{"worked":"Specific on the second try.","next":"Lead with specifics.","why":"Written-ready updates save her time."},"tags":[]},{"option_id":"B","text":"I''ll find out more and get back to you.","reaction":"When?","expression":"neutral","next_node_id":null,"ends_call":true,"effects":{"relationship":{"trust":-1,"respect":-1,"anger":1},"communication_7c":{"clear":2,"concise":2,"concrete":0,"correct":0,"coherent":2,"complete":1,"courteous":1},"business":0},"critical_flags":[],"recovery":false,"coaching":{"worked":"Honest.","next":"Say what you''ll find out and when.","why":"She''s still empty-handed."},"tags":[]}]}],"tags":["claim","carrier"]}'::jsonb);
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('coi','Certificate of insurance (COI)','A document that summarises a policy''s coverage for a third party. It informs; it doesn''t change the policy.',NULL,1,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('certificate_holder','Certificate holder','The person or company that receives the COI, often a general contractor or landlord.',NULL,1,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('additional_insured','Additional insured','A party added to a policy by an endorsement so it gets some protection under it. Only the carrier can add one.',NULL,1,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('endorsement','Endorsement','A written change to a policy issued by the carrier.',NULL,1,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('carrier','Carrier','The insurance company that issues the policy.',NULL,1,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('underwriter','Underwriter','The carrier''s specialist who evaluates risk and decides terms.',NULL,1,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('premium','Premium','The price of the policy.',NULL,1,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('renewal','Renewal','Continuing a policy for a new term, usually with updated terms and premium.',NULL,1,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('declarations_page','Declarations page','The summary page of a policy: insured, limits, dates, premium.',NULL,1,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('binding','Binding','Putting coverage into effect. Only authorised people can bind.',NULL,1,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('fnol','First notice of loss (FNOL)','The first report of a claim to the carrier.',NULL,1,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('adjuster','Adjuster','The person who investigates a claim and decides what''s covered.',NULL,1,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('loss_runs','Loss runs','A carrier''s report of a client''s claims history.',NULL,2,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('deductible','Deductible','The amount the insured pays before the policy pays.',NULL,2,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('limit','Limit','The most a policy will pay for a covered loss.',NULL,2,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('exclusion','Exclusion','Something a policy specifically doesn''t cover.',NULL,2,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('general_liability','General liability','Coverage for injury or property damage the business causes to others.',NULL,2,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('workers_comp','Workers'' compensation','Coverage for employees injured on the job.',NULL,2,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('commercial_auto','Commercial auto','Coverage for vehicles used for business.',NULL,2,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('umbrella','Umbrella policy','Extra liability coverage above other policies'' limits.',NULL,2,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('producer','Producer','The licensed agent who sells and advises on insurance.',NULL,3,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('csr','Customer service representative (CSR)','Agency staff who service existing policies.',NULL,3,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('quote','Quote','A carrier''s proposed terms and premium.',NULL,3,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('effective_date','Effective date','When coverage starts.',NULL,3,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('cancellation','Cancellation','Ending a policy before its term ends.',NULL,3,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('subrogation','Subrogation','A carrier recovering what it paid from the party at fault.',NULL,3,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('reserve','Reserve','Money a carrier sets aside to pay a claim.',NULL,3,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('waiver_of_subrogation','Waiver of subrogation','An agreement that the carrier won''t pursue a particular party. Requires an endorsement.',NULL,3,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('payroll_audit','Payroll audit','A carrier''s review of actual payroll to adjust the final premium.',NULL,3,'in_review');
INSERT INTO glossary_terms(id,term,meaning,example,level,status) VALUES ('e_and_o','Errors and omissions (E&O)','Coverage for professional mistakes; also why staying within authority matters.',NULL,3,'in_review');
INSERT INTO badges(id,name,description,tier,family,category,rarity,hidden,sort,criteria,art,status) VALUES ('c7_clear_1','Crystal Clear I','Rated Strong on Clear (plain words, one idea per sentence) in 3 calls',1,'c7_clear','communication','common',false,1,'{"all":[{"metric":"c7_strong_calls:clear","op":"gte","value":3}]}'::jsonb,'assets/badges/c7_clear_1.svg','in_review');
INSERT INTO badges(id,name,description,tier,family,category,rarity,hidden,sort,criteria,art,status) VALUES ('c7_clear_2','Crystal Clear II','Rated Strong on Clear (plain words, one idea per sentence) in 15 calls',2,'c7_clear','communication','rare',false,2,'{"all":[{"metric":"c7_strong_calls:clear","op":"gte","value":15}]}'::jsonb,'assets/badges/c7_clear_2.svg','in_review');
INSERT INTO badges(id,name,description,tier,family,category,rarity,hidden,sort,criteria,art,status) VALUES ('c7_clear_3','Crystal Clear III','Rated Strong on Clear (plain words, one idea per sentence) in 50 calls',3,'c7_clear','communication','epic',false,3,'{"all":[{"metric":"c7_strong_calls:clear","op":"gte","value":50}]}'::jsonb,'assets/badges/c7_clear_3.svg','in_review');
